if p == "/api/voice":
    # W7 round 4: "Hey Scout" (bestly-voice on this Pi) -> listening glow + chime, thinking, reply card on the wall
    if not self.client_address[0].startswith("127."):
        return self.send(403, '{"error":"pi only"}')
    b = self.body()
    ph = str(b.get("phase", ""))
    if ph not in ("listening", "thinking", "reply", "idle"):
        return self.send(400, '{"error":"bad phase"}')
    try:
        hold = max(3.0, min(40.0, float(b.get("hold") or 10)))
    except Exception:
        hold = 10.0
    with lock:
        VOICE.update({"seq": VOICE["seq"] + 1, "phase": ph, "at": time.time(), "chime": b.get("chime") is not False,
                      "heard": str(b.get("heard") or "")[:300], "reply": str(b.get("reply") or "")[:600], "hold": hold,
                      "audio": str(b.get("audio") or "")[:200] or None})
        version += 1
        lock.notify_all()
    return self.send(200, json.dumps({"ok": True, "seq": VOICE["seq"]}))

/* Hey Scout voice (W7 round 4): edge glow while listening/thinking + reply card (same footprint as the booking card) */
#vcGlow{position:absolute;inset:0;z-index:58;pointer-events:none;opacity:0;transition:opacity .5s var(--ease);border-radius:40px;overflow:hidden;}
#vcGlow.on{opacity:1;}
#vcGlow i{position:absolute;inset:0;border-radius:40px;}
#vcGlow i.a{box-shadow:inset 0 0 70px 14px rgba(94,92,230,.55);animation:vcBreath 1.8s ease-in-out infinite alternate;}
#vcGlow i.b{box-shadow:inset 0 0 110px 26px rgba(100,210,255,.28);animation:vcBreath 2.6s ease-in-out infinite alternate-reverse;}
#vcGlow.vc-thinking i.a{animation-duration:.9s;}
#vcGlow.vc-reply i{animation:none;opacity:.5;}
@keyframes vcBreath{from{opacity:.35}to{opacity:1}}
#vcCard{position:absolute;left:530px;top:22px;width:950px;height:256px;z-index:59;pointer-events:none;opacity:0;transform:translateY(-26px) scale(.96);
  transition:opacity .45s var(--ease),transform .7s var(--ease);}
#vcCard.on{opacity:1;transform:none;}
.vc-in{position:absolute;inset:0;display:flex;align-items:center;gap:28px;padding:0 38px;box-sizing:border-box;border-radius:44px;background:#1C1C1E;box-shadow:0 0 0 1.5px rgba(255,255,255,.1) inset;}
.vc-ico{flex:none;width:112px;height:112px;border-radius:56px;background:linear-gradient(135deg,var(--indigo),var(--teal));display:flex;align-items:center;justify-content:center;}
.vc-bars{display:flex;align-items:center;gap:7px;height:54px;}
.vc-bars i{display:block;width:9px;height:54px;border-radius:5px;background:#fff;transform:scaleY(.3);}
#vcCard.vc-listening .vc-bars i{animation:vcBar .9s ease-in-out infinite alternate;}
#vcCard.vc-thinking .vc-bars i{animation:vcBar 1.4s ease-in-out infinite alternate;opacity:.8;}
.vc-bars i:nth-child(2){animation-delay:.15s!important}.vc-bars i:nth-child(3){animation-delay:.3s!important}.vc-bars i:nth-child(4){animation-delay:.45s!important}.vc-bars i:nth-child(5){animation-delay:.6s!important}
@keyframes vcBar{from{transform:scaleY(.25)}to{transform:scaleY(1)}}
.vc-main{flex:1 1 auto;min-width:0;display:flex;flex-direction:column;gap:8px;max-height:216px;}
.vc-eye{font:700 22px/1 var(--sf);letter-spacing:.08em;text-transform:uppercase;color:var(--teal);}
.vc-q{font:500 24px/1.25 var(--sf);color:var(--label-2);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
.vc-t{font:700 44px/1.12 var(--sf);letter-spacing:-.02em;color:var(--label);max-height:150px;overflow:hidden;text-wrap:pretty;}
#vcCard.vc-listening .vc-t,#vcCard.vc-thinking .vc-t{font-size:56px;}
body.vc-on #board .right-area{opacity:0;transition:opacity .45s var(--ease);}

/* ================= Hey Scout voice (W7 round 4): listening chime + glow, thinking, reply card (+ projector-speaker fallback) ================= */
const VC={seq:-1,t:0};
function vcEl(){ const st=$('#stage'); if(!st) return {}; let g=$('#vcGlow'), c=$('#vcCard');
  if(!g){ g=document.createElement('div'); g.id='vcGlow'; g.setAttribute('aria-hidden','true'); g.innerHTML='<i class="a"></i><i class="b"></i>'; st.appendChild(g); }
  if(!c){ c=document.createElement('div'); c.id='vcCard'; c.setAttribute('aria-live','polite'); st.appendChild(c); }
  return {g,c}; }
function vcChime(){ try{ const c=SND.ctx; if(!c||c.state!=='running'||S.sound===false) return; const t=c.currentTime+.03;
    [[659.25,0],[987.77,.11]].forEach(([f,d])=>{ const o=c.createOscillator(), g=c.createGain(); o.type='sine'; o.frequency.value=f;
      g.gain.setValueAtTime(0,t+d); g.gain.linearRampToValueAtTime(.13,t+d+.015); g.gain.exponentialRampToValueAtTime(.0008,t+d+.42);
      o.connect(g); g.connect(c.destination); o.start(t+d); o.stop(t+d+.45); }); }catch(e){} }
function vcHide(){ const g=$('#vcGlow'), c=$('#vcCard'); if(g) g.className=''; if(c) c.classList.remove('on');
  setTimeout(()=>{ if(!(c&&c.classList.contains('on'))) document.body.classList.remove('vc-on'); },600); }
function vcTake(v){ if(!v||typeof v.seq!=='number'||v.seq===VC.seq) return; const first=VC.seq<0; VC.seq=v.seq;
  if(first&&(Date.now()/1000-(v.at||0))>20) return;          // a page reload never replays an old turn
  const {g,c}=vcEl(); if(!g) return; clearTimeout(VC.t);
  if(v.phase==='idle'){ vcHide(); return; }
  if(v.phase==='listening'&&v.chime!==false) vcChime();
  const title=v.phase==='listening'?'Listening…':v.phase==='thinking'?'Thinking…':esc(v.reply||'');
  c.className='vc-'+v.phase;
  c.innerHTML=`<div class="vc-in"><div class="vc-ico"><span class="vc-bars"><i></i><i></i><i></i><i></i><i></i></span></div><div class="vc-main"><div class="vc-eye">${v.phase==='reply'?'Scout':'Hey Scout'}</div>${v.heard&&v.phase==='reply'?`<div class="vc-q">“${esc(v.heard)}”</div>`:''}<div class="vc-t">${title}</div></div></div>`;
  g.className='on vc-'+v.phase; document.body.classList.add('vc-on'); void c.offsetWidth; c.classList.add('on');
  if(v.phase==='reply'){ try{ const f=c.querySelector('.vc-t'); let z=44; f.style.fontSize=z+'px'; while(f.scrollHeight>f.clientHeight+2&&z>26){ z-=2; f.style.fontSize=z+'px'; } }catch(x){}
    if(v.audio){ try{ const a=new Audio(v.audio); a.play().catch(()=>{}); }catch(x){} }
    VC.t=setTimeout(vcHide,(v.hold||10)*1000); }
  else VC.t=setTimeout(vcHide,v.phase==='listening'?15000:60000); }
